96	template <typename CType_>
97	__aicore__ inline void MegaMoe<CType_>::ProcessFixedGmm2(
98	    uint32_t physicalBlockId, GmmCommonPipeline& gmmPipeline, const GmmClaimedTask& initialTask)
99	{
100	    const __gm__ MegaMoeFixedGroupTiling& fixed = tilingData_->fixedGroupTiling;
101	    const bool mailboxGmm1 = tilingData_->gmmSchedulerTiling.gmm1ScheduleMode == kMegaMoeGmm1ScheduleWave0MailboxSuffix;
102	    const bool localFixedHandoff =
103	        fixed.fullAicGmm1WaveCount > kMegaMoeFullAicGmm1WaveCount && physicalBlockId >= fixed.gmm1GroupSize;
104	    if (mailboxGmm1) {
105	        WaitGmm2EntryReady(workspaceGM_, tilingData_);
106	    } else if (localFixedHandoff) {
107	        WaitCombineConsumerArmed(workspaceGM_, tilingData_, physicalBlockId);
108	    } else {
109	        WaitGmm2ConsumerReady(workspaceGM_, tilingData_, physicalBlockId);
110	    }
111	    Gmm2 gmm2;
112	    gmm2.Init(weight2GM_, weightScale2GM_, workspaceGM_, tilingData_);
113	    gmm2.ProcessFixed(physicalBlockId, gmmPipeline, initialTask);
114	}
115	#endif
116	
117	template <typename CType_>
118	__aicore__ inline void MegaMoe<CType_>::ProcessFixedGroups()
119	{
120	    const __gm__ MegaMoeFixedGroupTiling& fixed = tilingData_->fixedGroupTiling;
121	    const uint32_t physicalBlockId = get_block_idx();
122	
123	#if defined(__DAV_CUBE__)
124	    const bool fixedWaveGmm1 = tilingData_->gmmSchedulerTiling.gmm1ScheduleMode == kMegaMoeGmm1ScheduleFixedWave;
125	    if (fixedWaveGmm1) {
126	        // Fixed-wave GMM1 owns its local pipeline; GMM2 starts with a fresh one.
127	        ProcessFixedGmm1(physicalBlockId, nullptr);
128	        if (physicalBlockId < fixed.gmm1GroupSize) {
129	            pipe_barrier(PIPE_ALL);
130	            dsb(DSB_DDR);
131	            PublishGmmMailboxProgress(
132	                workspaceGM_, tilingData_->gmmSchedulerTiling.mailbox, physicalBlockId, kGmmMailboxGmm1Wave0EndTicket);
133	        }
134	        GmmCommonPipeline gmm2Pipeline;
135	        const GmmClaimedTask noInitialTask;
136	        ProcessFixedGmm2(physicalBlockId, gmm2Pipeline, noInitialTask);
137	    } else {
138	        // Mailbox handoff carries the first GMM2 task and reuses the GMM pipeline.
139	        GmmCommonPipeline sharedPipeline;
140	        const GmmClaimedTask initialGmm2 = ProcessFixedGmm1(physicalBlockId, &sharedPipeline);
141	        ProcessFixedGmm2(physicalBlockId, sharedPipeline, initialGmm2);
142	    }
143	#elif defined(__DAV_VEC__)
144	    const uint32_t subblockId = get_subblockid();
145	    const uint32_t dispatchRankSize = tilingData_->runtimeInfo.rankSize;
146	    const uint32_t dispatchLanesPerRank = fixed.dispatchGroupSize / dispatchRankSize;
147	    const uint32_t dispatchActiveWorkerCount = dispatchRankSize * dispatchLanesPerRank;
148	    const bool gmm1Mailbox = tilingData_->gmmSchedulerTiling.gmm1ScheduleMode == kMegaMoeGmm1ScheduleWave0MailboxSuffix;
149	
150	    const uint32_t rankStreamingWorkerCount = fixed.physicalAicNum * kMegaMoeFixedAivSubblocksPerPhysicalBlock;
151	    const uint32_t producerPhysicalBlockId = fixed.physicalAicNum - 1U;
152	    const uint32_t progressPhysicalBlockId = producerPhysicalBlockId - 1U;
153	    const bool gmmTaskProducerRole = subblockId == 0U && physicalBlockId == producerPhysicalBlockId;
154	
155	    // GMM2's mailbox is always active. The producer waits for the front
156	    // metadata marker, then schedules both direct-wave suffixes.
157	    if (gmmTaskProducerRole) {
158	        MegaMoeGmmTaskProducer producer;
159	        producer.Init(workspaceGM_, tilingData_);
160	        producer.Process();
161	    }
162	
163	    // AIV0s between Dispatch and the final Producer build route metadata.
164	    if (subblockId == 0U && physicalBlockId >= fixed.dispatchGroupSize && physicalBlockId < producerPhysicalBlockId) {
165	        const uint32_t metadataWorkerIdx = physicalBlockId - fixed.dispatchGroupSize;
166	        const uint32_t metadataWorkerCount = producerPhysicalBlockId - fixed.dispatchGroupSize;
167	        deferred_route_metadata::DeferredRouteMetadata metadata;
168	        metadata.Init(expertIdGM_, workspaceGM_, tilingData_, metadataWorkerIdx, metadataWorkerCount);
169	        metadata.Run();
170	        if (metadataWorkerIdx == 0U) {
171	            // Expanded metadata, local Dispatch and every source-rank preSum
172	            // must be visible before any GMM2 consumer enters the mailbox.
173	            WaitEpochAcquire(
174	                FixedSyncSlot(workspaceGM_, tilingData_, kMegaMoeFixedSyncDispatchDoneSlot),
175	                kMegaMoeFixedDispatchDoneMarker);
176	            PtoRemoteWindow remoteWindow;
177	            remoteWindow.Init(reinterpret_cast<GM_ADDR>(tilingData_->runtimeInfo.remoteWindowContext));
178	            const int32_t preSumEpoch = remoteWindow.FrontReadyEpoch();
179	            for (uint32_t srcRank = 0U; srcRank < tilingData_->runtimeInfo.rankSize; ++srcRank) {
180	                remoteWindow.WaitPreSumReady(static_cast<int32_t>(srcRank), preSumEpoch);
181	            }
182	            PublishGmm2EntryReady(workspaceGM_, tilingData_);
183	        }
184	        if (physicalBlockId == progressPhysicalBlockId) {
185	            Gmm2ExpertProgressCoordinator coordinator;
186	            coordinator.Init(workspaceGM_, tilingData_);
187	            coordinator.Process();
188	        }
189	    }
190	
191	    if (subblockId == 0U && physicalBlockId < dispatchActiveWorkerCount) {
192	        DispatchGather dispatchGather;
193	        dispatchGather.Init(workspaceGM_, tilingData_);
194	        dispatchGather.ProcessFixed(physicalBlockId, fixed.dispatchGroupSize);
195	        pipe_barrier(PIPE_ALL);
196	        dsb(DSB_DDR);
197	        PtoRemoteWindow remoteWindow;
198	        remoteWindow.Init(reinterpret_cast<GM_ADDR>(tilingData_->runtimeInfo.remoteWindowContext));
199	        const int32_t epoch = remoteWindow.DataReadyEpoch();
200	        remoteWindow.PublishDispatchRelease(physicalBlockId, epoch);
201	        if (physicalBlockId == 0U) {
202	            // Some topologies leave a trailing Dispatch role unused after
203	            // rank-balanced lane assignment.
204	            remoteWindow.WaitDispatchReleaseMte(dispatchActiveWorkerCount, epoch);
205	            PublishScalarEpoch(
206	                FixedSyncSlot(workspaceGM_, tilingData_, kMegaMoeFixedSyncDispatchDoneSlot),
207	                kMegaMoeFixedDispatchDoneMarker);
208	        }
209	    }
210	
211	    if (subblockId == 1U) {
212	        Swiglu<CType_> swiglu;
213	        swiglu.Init(workspaceGM_, tilingData_);
214	        swiglu.ProcessFixed(physicalBlockId, fixed.physicalAicNum);
215	
216	        const bool localFixedHandoff =
217	            fixed.fullAicGmm1WaveCount > kMegaMoeFullAicGmm1WaveCount && physicalBlockId >= fixed.gmm1GroupSize;
218	        if (!localFixedHandoff) {
219	            pipe_barrier(PIPE_ALL);
220	            dsb(DSB_DDR);
221	            PublishCombineConsumerArmed(workspaceGM_, tilingData_, physicalBlockId);
222	            WaitGmm2EntryReady(workspaceGM_, tilingData_);
223	        }
224	        Combine<bfloat16_t> combine;
225	        combine.Init(workspaceGM_, tilingData_);
226	        combine.ProcessFixed(physicalBlockId);
227	    }
228	
229	    // Rank-streaming uses stable logical ordinals: AIV1 is [0, P), AIV0 is
230	    // [P, 2P). The dedicated coordinator publishes live expert progress;
231	    // the phase-1 coordinator only snapshots progress for two-phase cases.
232	    const uint32_t rankStreamingWorkerIdx = subblockId == 1U ? physicalBlockId : fixed.physicalAicNum + physicalBlockId;
233	    const bool twoPhaseUnpermute = tilingData_->unpermuteTiling.rankStreamingInitialWorkerCount != 0U;
234	    const bool rankStreamingCoordinator = rankStreamingWorkerIdx == fixed.physicalAicNum;
235	    if (twoPhaseUnpermute && rankStreamingCoordinator) {
236	        // Group1 handoff is owned by each AIC. Fixed-wave GMM1 publishes its
237	        // final wave epoch; mailbox GMM1 publishes the done marker only after
238	        // the AIC has claimed its GMM2 transition ticket.
239	        const int32_t gmm1HandoffEpoch =
240	            gmm1Mailbox ? kMegaMoeFixedGmm1DoneMarker :
241	                          static_cast<int32_t>(fixed.totalWaveCount + kMegaMoeFixedGmm1GroupDoneEpochOffset);
242	        WaitArrivalMinMte(
243	            workspaceGM_, tilingData_, kMegaMoeFixedSyncGmm1ArrivalBase, fixed.gmm1GroupSize, gmm1HandoffEpoch);
244	        PtoRemoteWindow remoteWindow;
245	        remoteWindow.Init(reinterpret_cast<GM_ADDR>(tilingData_->runtimeInfo.remoteWindowContext));
246	        const int32_t epoch = remoteWindow.DataReadyEpoch();
247	        const uint32_t rankCount = tilingData_->runtimeInfo.rankSize;
248	        const uint32_t expertPerRank = tilingData_->megaMoeInfo.expertPerRank;
249	        uint32_t readyExpertCounts[COMBINE_EXPERT_PROGRESS_MAX_RANKS] = {0U};
250	        remoteWindow.ReadExpertProgressMte(epoch, expertPerRank, readyExpertCounts);
251	        uint32_t readyRankMask = 0U;
252	        for (uint32_t producerRank = 0U; producerRank < rankCount; ++producerRank) {
253	            if (readyExpertCounts[producerRank] != 0U) {
254	                readyRankMask |= 1U << producerRank;
255	            }
256	        }
257	        remoteWindow.AcquireDataReady();
258	        remoteWindow.PublishUnpermutePhase1Progress(readyExpertCounts, rankCount, readyRankMask, epoch);
259	    }
260	
261	    Unpermute<bfloat16_t> unpermute;
262	    if (!unpermute.Init(
263	            workspaceGM_, expertIdGM_, probsGM_, outGM_, tilingData_, rankStreamingWorkerIdx,
264	            rankStreamingWorkerCount)) {
265	        return;
266	    }
267	    unpermute.Process();
268	#endif
269	}
270	
271	template <typename CType_>
272	__aicore__ inline void MegaMoe<CType_>::Process()
273	{
274	#if defined(__DAV_VEC__)
275	    FrontReorderProcess<CType_>(xGM_, expertIdGM_, expertTokenNumsGM_, workspaceGM_, tilingData_);
276	#endif
277	    ProcessFixedGroups();
278	}
279	
280	#endif // DISPATCH_MEGA_COMBINE_H
