113	    AICORE inline volatile __gm__ int32_t* DispatchReadyCountSlot(uint32_t groupIdx, uint32_t blockM) const
114	    {
115	        const __gm__ MegaMoeDispatchTiling& dispatch = tilingData_->dispatchTiling;
116	        const uint64_t byteOffset =
117	            dispatch.readyCountOffset +
118	            static_cast<uint64_t>(groupIdx) * dispatch.readyCountMaxTilesPerExpert * kMegaMoeReadyCountSlotBytes +
119	            static_cast<uint64_t>(blockM) * kMegaMoeReadyCountSlotBytes;
