122	    AICORE inline void WaitDispatchTileReady(uint32_t groupIdx, const GmmCommonTileInfo& tileInfo) const
123	    {
124	        volatile __gm__ int32_t* slot = DispatchReadyCountSlot(groupIdx, tileInfo.blockM);
125	        const int32_t targetRows = static_cast<int32_t>(tileInfo.actualM);
126	        int32_t observedRows = 0;
127	        do {
128	            dcci((__gm__ void*)slot, SINGLE_CACHE_LINE);
129	            dsb(DSB_DDR);
130	            observedRows = *slot;
131	            if (observedRows != targetRows) {
132	                EpochPollBackoff();
133	            }
134	        } while (observedRows != targetRows);
135	        dsb(DSB_DDR);
