137	    AICORE inline void BuildGmmPairRuns(
138	        const MegaMoeGmmTask& task, const GmmCommonTileInfo& tileInfo, uint32_t dataSlotBase, uint32_t scaleSlotBase,
139	        Gmm1Pipeline::TileRun& xRun, Gmm1Pipeline::TileRun& gateRun) const
140	    {
141	        const uint32_t scaleLeadingDim = problemK_ / kMegaMoeMxGroupSize;
142	        const uint64_t gmOffsetA = static_cast<uint64_t>(task.expertBase + tileInfo.blockRowStart) * problemK_;
143	        const uint64_t gmOffsetAScale =
144	            static_cast<uint64_t>(task.expertBase + tileInfo.blockRowStart) * scaleLeadingDim;
145	        const uint64_t weightExpertStride = static_cast<uint64_t>(problemN_) * problemK_;
146	        const uint64_t weightScaleExpertStride = static_cast<uint64_t>(problemN_) * scaleLeadingDim;
147	        const uint64_t weightExpertBase = static_cast<uint64_t>(task.expert) * weightExpertStride;
148	        const uint64_t weightScaleExpertBase = static_cast<uint64_t>(task.expert) * weightScaleExpertStride;
149	        const uint64_t xOffset = weightExpertBase + static_cast<uint64_t>(tileInfo.blockColStart) * problemK_;
150	        const uint64_t gateOffset =
151	            weightExpertBase + static_cast<uint64_t>(outputN_ + tileInfo.blockColStart) * problemK_;
152	        const uint64_t xScaleOffset =
153	            weightScaleExpertBase + static_cast<uint64_t>(tileInfo.blockColStart) * scaleLeadingDim;
154	        const uint64_t gateScaleOffset =
