156	        const uint32_t gateDataSlotBase = Gmm1Pipeline::AdvanceDataSlotBase(dataSlotBase, problemK_);
157	        const uint32_t gateScaleSlotBase = Gmm1Pipeline::AdvanceScaleSlotBase(scaleSlotBase, problemK_);
158	        xRun = Gmm1Pipeline::TileRun{
159	            gmAPtr_ + gmOffsetA,
160	            gmAScalePtr_ + gmOffsetAScale,
161	            weight1Ptr_ + xOffset,
162	            weightScale1Ptr_ + xScaleOffset,
163	            tileInfo.actualM,
164	            tileInfo.actualN,
165	            problemK_,
166	            problemK_,
167	            scaleLeadingDim,
168	            problemK_,
169	            scaleLeadingDim,
170	            dataSlotBase,
171	            scaleSlotBase};
172	        gateRun = Gmm1Pipeline::TileRun{
173	            gmAPtr_ + gmOffsetA,
174	            gmAScalePtr_ + gmOffsetAScale,
175	            weight1Ptr_ + gateOffset,
176	            weightScale1Ptr_ + gateScaleOffset,
177	            tileInfo.actualM,
178	            tileInfo.actualN,
179	            problemK_,
180	            problemK_,
181	            scaleLeadingDim,
182	            problemK_,
183	            scaleLeadingDim,
184	            gateDataSlotBase,
185	            gateScaleSlotBase};
186	    }
