192	        Gmm1Pipeline& gmmPipeline, Gmm1SwigluCvPipe& cvPipe, uint32_t groupIdx, uint32_t groupBase,
193	        const GmmCommonTileInfo& tileInfo) const
194	    {
195	        const uint32_t scaleLeadingDim = problemK_ / kMegaMoeMxGroupSize;
196	        const uint64_t gmOffsetA = static_cast<uint64_t>(groupBase + tileInfo.blockRowStart) * problemK_;
197	        const uint64_t gmOffsetAScale = static_cast<uint64_t>(groupBase + tileInfo.blockRowStart) * scaleLeadingDim;
198	        const uint64_t weightExpertStride = static_cast<uint64_t>(problemN_) * problemK_;
199	        const uint64_t weightScaleExpertStride = static_cast<uint64_t>(problemN_) * scaleLeadingDim;
200	        const uint64_t weightExpertBase = static_cast<uint64_t>(groupIdx) * weightExpertStride;
201	        const uint64_t weightScaleExpertBase = static_cast<uint64_t>(groupIdx) * weightScaleExpertStride;
202	        const uint64_t xOffset = weightExpertBase + static_cast<uint64_t>(tileInfo.blockColStart) * problemK_;
