254	    gmAScalePtr_ = reinterpret_cast<__gm__ float8_e8m0_t*>(workspaceGM + tilingData_->dispatchTiling.gmAScaleOffset);
255	    weight1Ptr_ = reinterpret_cast<__gm__ float8_e4m3_t*>(weight1GM);
