259	AICORE inline GmmClaimedTask Gmm1::ProcessFixed(uint32_t groupLocalId, uint32_t groupSize, Gmm1Pipeline* gmmPipeline)
260	{
261	    coreIdx_ = groupLocalId;
262	    coreNum_ = groupSize;
263	    GmmClaimedTask controlResult;
264	    if (tilingData_->gmmSchedulerTiling.gmm1ScheduleMode == kMegaMoeGmm1ScheduleFixedWave) {
265	        ProcessFixedWave();
266	        return controlResult;
267	    }
268	
269	    WaitEpochAcquire(
270	        FixedSyncSlot(workspaceGM_, tilingData_, kMegaMoeFixedSyncFrontMetadataReadySlot),
271	        kMegaMoeFixedFrontMetadataReadyMarker);
272	    Gmm1SwigluCvPipe cvPipe;
273	    const GmmClaimedTask initialTask = ProcessDirectWave0(cvPipe, *gmmPipeline);
274	    const bool group2DirectGmm2 = coreIdx_ >= tilingData_->fixedGroupTiling.gmm1GroupSize;
275	    if (group2DirectGmm2) {
276	        // GMM2 reuses the intra-block event ids from the GMM1->SwiGLU pipe.
277	        // Consume the final payload credit before this physical block enters GMM2.
278	        Gmm1SwigluProducerDrain(cvPipe);
279	        return initialTask;
280	    }
281	    return ProcessMailbox(*gmmPipeline, cvPipe, initialTask);
282	}
