284	AICORE inline void Gmm1::ProcessFixedWave()
285	{
286	    WaitEpochAcquire(
287	        FixedSyncSlot(workspaceGM_, tilingData_, kMegaMoeFixedSyncFrontMetadataReadySlot),
288	        kMegaMoeFixedFrontMetadataReadyMarker);
289	    Gmm1SwigluCvPipe cvPipe;
290	    Gmm1Pipeline gmmPipeline;
291	    uint32_t groupBase = 0;
292	    MegaMoeCoreTileBalancer tileBalancer;
293	    const __gm__ MegaMoeFixedGroupTiling& fixed = tilingData_->fixedGroupTiling;
294	    for (uint32_t waveIdx = 0U; waveIdx < fixed.totalWaveCount; ++waveIdx) {
295	        coreNum_ = waveIdx < fixed.fullAicGmm1WaveCount ? fixed.physicalAicNum : fixed.gmm1GroupSize;
296	        if (coreIdx_ >= coreNum_) {
297	            break;
298	        }
299	        SetCoreTileBalancerRange(tileBalancer, 0U, coreNum_);
300	        const MegaMoeExpertWaveRange wave = GetExpertWaveRange(
301	            waveIdx, expertPerRank_, fixed.fullAicExpertsPerWave, fixed.expertsPerWave, fixed.fullAicGmm1WaveCount);
302	        for (uint32_t groupIdx = wave.begin; groupIdx < wave.end; ++groupIdx) {
303	            const uint32_t currentM = MoeCurrentMRaw(cumsumMMPtr_, rankSize_, expertPerRank_, groupIdx);
304	            const uint32_t coreLoops = CoreLoops(currentM);
305	            const uint32_t startCoreIdx = SelectCoreTileStart(tileBalancer, coreLoops);
306	            const uint32_t startLoopIdx = StartLoopIdx(startCoreIdx);
307	            for (uint32_t loopIdx = startLoopIdx; loopIdx < coreLoops; loopIdx += coreNum_) {
308	                const GmmCommonTileInfo tileInfo = BuildTileInfo(currentM, loopIdx);
309	                WaitDispatchTileReady(groupIdx, tileInfo);
310	                RunGmmPair(gmmPipeline, cvPipe, groupIdx, groupBase, tileInfo);
311	            }
312	            groupBase += currentM;
313	            CommitCoreTileAssignment(tileBalancer, startCoreIdx, coreLoops);
314	        }
315	        // The CV FIFO carries tile completion; retain a per-AIC wave marker for
316	        // zero-tile participants and the existing wave-to-GMM2 control path.
317	        pipe_barrier(PIPE_FIX);
318	        PublishGroupArrival(workspaceGM_, tilingData_, kMegaMoeFixedSyncGmm1ArrivalBase, coreIdx_, waveIdx);
319	    }
320	    pipe_barrier(PIPE_FIX);
321	    Gmm1SwigluProducerDrain(cvPipe);
322	    if (coreIdx_ < fixed.gmm1GroupSize) {
323	        pipe_barrier(PIPE_ALL);
324	        PublishScalarEpoch(
325	            FixedSyncSlot(workspaceGM_, tilingData_, kMegaMoeFixedSyncGmm1ArrivalBase + coreIdx_),
326	            static_cast<int32_t>(fixed.totalWaveCount + kMegaMoeFixedGmm1GroupDoneEpochOffset));
327	    }
328	}
