330	AICORE inline GmmClaimedTask Gmm1::WaitGmm1Successor(
331	    GmmMailboxConsumerCursor& mailboxCursor, GmmMailboxTicketProbe* successorProbe, uint32_t dataSlotBase,
332	    uint32_t scaleSlotBase)
333	{
334	    const __gm__ MegaMoeGmmMailboxTiling& mailbox = tilingData_->gmmSchedulerTiling.mailbox;
335	    GmmClaimedTask next = WaitGmmMailboxTask(
336	        workspaceGM_, mailbox, tilingData_->gmmSchedulerTiling.gmm1, kGmmMailboxFirstTaskTicket, coreIdx_,
337	        mailboxCursor, GmmTaskStage::kGmm1, successorProbe);
338	    const bool nextIsGmm2 = next.ticket >= mailbox.gmm2TicketBase && next.ticket < kGmmMailboxTerminalTicket;
339	    if (next.stageTransition) {
340	        next = ResolveGmmMailboxStageTransition(
341	            workspaceGM_, tilingData_->gmmSchedulerTiling.gmm2, mailbox.gmm2TicketBase, next);
342	    }
343	    if (!next.valid) {
344	        return next;
345	    }
346	
347	    next.dataSlotBase = dataSlotBase;
348	    next.scaleSlotBase = scaleSlotBase;
349	    return next;
350	}
