352	AICORE inline GmmClaimedTask Gmm1::ProcessDirectWave0(Gmm1SwigluCvPipe& cvPipe, Gmm1Pipeline& gmmPipeline)
353	{
354	    GmmClaimedTask successor;
355	    const __gm__ MegaMoeFixedGroupTiling& fixed = tilingData_->fixedGroupTiling;
356	    const MegaMoeExpertWaveRange wave = GetExpertWaveRange(
357	        0U, expertPerRank_, fixed.fullAicExpertsPerWave, fixed.expertsPerWave, fixed.fullAicGmm1WaveCount);
358	    coreNum_ = fixed.physicalAicNum;
359	    DirectWaveCursor directCursor;
360	    directCursor.Init(this, wave.end);
361	    const bool hasDirectAssignment = directCursor.Advance();
362	
363	    const __gm__ MegaMoeGmmMailboxTiling& mailbox = tilingData_->gmmSchedulerTiling.mailbox;
364	    GmmMailboxConsumerCursor mailboxCursor;
365	    const bool group2DirectGmm2 = coreIdx_ >= fixed.gmm1GroupSize;
366	    if (!hasDirectAssignment) {
367	        PublishGmmMailboxProgress(workspaceGM_, mailbox, coreIdx_, kGmmMailboxGmm1Wave0EndTicket);
368	        if (group2DirectGmm2) {
369	            return successor;
370	        }
371	        GmmMailboxTicketProbe successorProbe;
372	        ProbeGmmMailboxSuccessorTicket(workspaceGM_, mailbox, coreIdx_, kGmmMailboxGmm1Wave0EndTicket, successorProbe);
373	        return WaitGmm1Successor(mailboxCursor, &successorProbe, 0U, 0U);
374	    }
375	
376	    while (true) {
377	        const DirectWaveAssignment assignment = directCursor.Current();
378	        const MegaMoeGmmTask task = assignment.task;
379	        const GmmCommonTileInfo tileInfo = assignment.tileInfo;
380	        WaitDispatchTileReady(task.expert, tileInfo);
381	        Gmm1Pipeline::TileRun xRun;
382	        Gmm1Pipeline::TileRun gateRun;
383	        BuildGmmPairRuns(task, tileInfo, 0U, 0U, xRun, gateRun);
384	        GmmDirectWaveNextAssignmentProbe<DirectWaveCursor> panelProbe(
385	            workspaceGM_, mailbox, coreIdx_, kGmmMailboxGmm1Wave0EndTicket, directCursor, GmmTaskStage::kGmm1);
386	        gmmPipeline.ComputePairDirect(cvPipe, xRun, gateRun, panelProbe);
387	        const bool finalLocalTile = !panelProbe.HasNextAssignment();
388	        const uint32_t nextDataSlotBase = Gmm1Pipeline::AdvanceDataSlotBase(gateRun.dataSlotBase, problemK_);
389	        const uint32_t nextScaleSlotBase = Gmm1Pipeline::AdvanceScaleSlotBase(gateRun.scaleSlotBase, problemK_);
390	        GmmMailboxTicketProbe* successorProbe = panelProbe.SuccessorProbe();
391	        if (finalLocalTile && !group2DirectGmm2 && successorProbe->ready) {
392	            successor = WaitGmm1Successor(mailboxCursor, successorProbe, nextDataSlotBase, nextScaleSlotBase);
393	        }
394	        gmmPipeline.EnqueuePairDirect(cvPipe, tileInfo.actualM, tileInfo.actualN);
395	        gmmPipeline.RecordPairDirect(cvPipe);
396	        if (finalLocalTile && !group2DirectGmm2 && successor.ticket == kGmmMailboxEmptyTicket) {
397	            successor = WaitGmm1Successor(mailboxCursor, successorProbe, nextDataSlotBase, nextScaleSlotBase);
398	        }
399	        if (finalLocalTile) {
400	            gmmPipeline.DrainPairDirectStore();
401	        }
402	        if (finalLocalTile) {
403	            break;
404	        }
405	    }
406	    return successor;
407	}
408	
409	AICORE inline GmmClaimedTask Gmm1::ProcessMailbox(
410	    Gmm1Pipeline& gmmPipeline, Gmm1SwigluCvPipe& cvPipe, const GmmClaimedTask& initialTask)
411	{
412	    GmmClaimedTask controlResult;
413	    const __gm__ MegaMoeGmmMailboxTiling& mailbox = tilingData_->gmmSchedulerTiling.mailbox;
414	    uint32_t dataSlotBase = initialTask.dataSlotBase;
415	    uint32_t scaleSlotBase = initialTask.scaleSlotBase;
416	
417	    GmmMailboxConsumerCursor mailboxCursor = initialTask.mailboxCursor;
418	    GmmClaimedTask current;
419	    if (initialTask.ticket != kGmmMailboxEmptyTicket) {
420	        current = initialTask;
421	    } else {
422	        current = WaitGmmMailboxTask(
423	            workspaceGM_, mailbox, tilingData_->gmmSchedulerTiling.gmm1, kGmmMailboxFirstTaskTicket, coreIdx_,
424	            mailboxCursor, GmmTaskStage::kGmm1, nullptr);
425	    }
426	    if (current.stageTransition) {
427	        current = ResolveGmmMailboxStageTransition(
428	            workspaceGM_, tilingData_->gmmSchedulerTiling.gmm2, mailbox.gmm2TicketBase, current);
429	    }
430	    const bool initialIsGmm2 = current.ticket >= mailbox.gmm2TicketBase && current.ticket < kGmmMailboxTerminalTicket;
431	    if (current.valid && !initialIsGmm2) {
432	        PublishGmm1SwigluControl(cvPipe, current.task);
433	    }
434	    while (current.valid && !initialIsGmm2) {
435	        const MegaMoeGmmTask currentTask = current.task;
436	        const GmmCommonTileInfo tileInfo =
437	            GmmCommonBuildTileInfoFromCoord(currentTask.currentM, outputN_, currentTask.blockM, currentTask.blockN);
438	        Gmm1Pipeline::TileRun xRun;
439	        Gmm1Pipeline::TileRun gateRun;
440	        BuildGmmPairRuns(currentTask, tileInfo, dataSlotBase, scaleSlotBase, xRun, gateRun);
441	        GmmMailboxPanelProbe panelProbe(workspaceGM_, mailbox, coreIdx_, current.ticket, GmmTaskStage::kGmm1);
442	        gmmPipeline.ComputePairDirect(cvPipe, xRun, gateRun, panelProbe);
443	        const uint32_t nextDataSlotBase = Gmm1Pipeline::AdvanceDataSlotBase(gateRun.dataSlotBase, problemK_);
444	        const uint32_t nextScaleSlotBase = Gmm1Pipeline::AdvanceScaleSlotBase(gateRun.scaleSlotBase, problemK_);
445	        GmmMailboxTicketProbe* successorProbe = panelProbe.SuccessorProbe();
446	        GmmClaimedTask next;
447	        if (successorProbe->ready) {
448	            next = WaitGmm1Successor(mailboxCursor, successorProbe, nextDataSlotBase, nextScaleSlotBase);
449	        }
450	        gmmPipeline.EnqueuePairDirect(cvPipe, tileInfo.actualM, tileInfo.actualN);
451	        gmmPipeline.RecordPairDirect(cvPipe);
452	        if (next.ticket == kGmmMailboxEmptyTicket) {
453	            next = WaitGmm1Successor(mailboxCursor, successorProbe, nextDataSlotBase, nextScaleSlotBase);
454	        }
455	        const bool nextIsGmm2 = next.ticket >= mailbox.gmm2TicketBase && next.ticket < kGmmMailboxTerminalTicket;
456	        if (next.valid && !nextIsGmm2) {
457	            PublishGmm1SwigluControl(cvPipe, next.task);
458	        }
459	        gmmPipeline.DrainPairDirectStore();
460	        dataSlotBase = nextDataSlotBase;
461	        scaleSlotBase = nextScaleSlotBase;
462	        current = next;
463	        if (nextIsGmm2) {
464	            break;
465	        }
466	    }
467	    const bool terminalTicketContinuesToGmm2 = (current.task.flags & kGmmTaskFlagTerminal) != 0U;
468	    const bool nextTicketIsGmm2 =
469	        current.ticket >= mailbox.gmm2TicketBase && current.ticket < kGmmMailboxTerminalTicket;
470	    const bool continuesWithGmm2 = nextTicketIsGmm2 || terminalTicketContinuesToGmm2;
471	
472	    // GMM2 reuses the event ids from both GMM1->SwiGLU rings. Always drain
473	    // the outstanding payload credit, including the mailbox transition path.
474	    Gmm1SwigluProducerDrain(cvPipe);
475	    PublishGmm1SwigluControl(cvPipe, Gmm1SwigluStageEndControl());
476	    // Drain the stage-end control acknowledgement before GMM2 can reuse the
477	    // control event ids as free credits.
478	    Gmm1SwigluControlProducerDrain(cvPipe);
479	    pipe_barrier(PIPE_FIX);
480	    if (current.ticket != kGmmMailboxEmptyTicket && !nextTicketIsGmm2 && !terminalTicketContinuesToGmm2) {
481	        PublishGmmMailboxProgress(workspaceGM_, mailbox, coreIdx_, current.ticket);
482	    }
483	    controlResult = current;
484	    // Group1 reaches this point only after resolving its GMM1-to-GMM2 handoff.
485	    if (!continuesWithGmm2) {
486	        pipe_barrier(PIPE_ALL);
487	    }
488	    PublishScalarEpoch(
489	        FixedSyncSlot(workspaceGM_, tilingData_, kMegaMoeFixedSyncGmm1ArrivalBase + coreIdx_),
490	        kMegaMoeFixedGmm1DoneMarker);
491	    return controlResult;
492	}
493	
494	#endif // DISPATCH_MEGA_COMBINE_GMM1_H
