58	AICORE inline GmmMailboxLanePhase ObserveGmmMailboxWave0End(
59	    GmmMailboxLanePhase phase, bool group2Lane, bool gmm1Wave0End, bool gmm2Wave0End)
60	{
61	    if (phase == GmmMailboxLanePhase::kAwaitGmm1Wave0End) {
62	        if (group2Lane && gmm2Wave0End) {
63	            return GmmMailboxLanePhase::kGmm2Pc;
