74	AICORE inline GmmMailboxLanePhase AdvanceGmmMailboxLanePhase(
75	    GmmMailboxLanePhase phase, bool gmm1SuffixPublished, bool gmm2GateReady, bool gmm2SuffixPublished)
76	{
77	    if (phase == GmmMailboxLanePhase::kGmm1Pc && gmm1SuffixPublished) {
78	        return gmm2GateReady ? GmmMailboxLanePhase::kGmm2Pc : phase;
79	    }
80	    if (phase == GmmMailboxLanePhase::kGmm2Pc && gmm2SuffixPublished) {
81	        return GmmMailboxLanePhase::kTerminalReady;
82	    }
83	    return phase;
84	}
