224	    AICORE inline __gm__ int32_t* ReadyCounterSlot(uint32_t stage, uint32_t expert, uint32_t blockM) const
225	    {
226	        if (stage == static_cast<uint32_t>(MailboxStage::kGmm1)) {
227	            return const_cast<__gm__ int32_t*>(DispatchReadySlot(expert, blockM));
228	        }
229	        return GmmTaskDependencySlot(
230	            workspaceGM_, tilingData_->gmmSchedulerTiling.gmm2, tilingData_->dispatchTiling.readyCountMaxTilesPerExpert,
231	            expert, blockM);
