234	    AICORE inline uint32_t ReadyCounterExpected(
235	        uint32_t stage, const ExpertTaskLayout& layout, uint32_t expert, uint32_t blockM) const
236	    {
237	        if (stage == static_cast<uint32_t>(MailboxStage::kGmm2)) {
238	            constexpr uint32_t gmm1Stage = static_cast<uint32_t>(MailboxStage::kGmm1);
239	            return layout.taskBase[gmm1Stage][expert + 1U] - layout.taskBase[gmm1Stage][expert];
240	        }
241	        const uint32_t rowBegin = blockM * kMegaMoeGmmTileM;
242	        const uint32_t remaining = layout.currentM[expert] - rowBegin;
243	        return remaining < kMegaMoeGmmTileM ? remaining : kMegaMoeGmmTileM;
244	    }
