246	    AICORE inline void LoadReadyExpertSnapshot(uint32_t stage, uint32_t expert, uint32_t blockMCount) const
247	    {
248	        using SnapshotTile = PtoVecTile<uint32_t, kGmmProducerReadySnapshotMaxBlockM>;
249	        SnapshotTile snapshot(1, blockMCount);
250	        pto::TASSIGN(snapshot, kGmmProducerReadySnapshotUbBase);
251	        __gm__ uint8_t* src = reinterpret_cast<__gm__ uint8_t*>(ReadyCounterSlot(stage, expert, 0U));
252	        const uint64_t srcStride = stage == static_cast<uint32_t>(MailboxStage::kGmm1) ? kMegaMoeReadyCountSlotBytes :
253	                                                                                         kMegaMoeFixedSyncSlotBytes;
254	        LoadGmmSnapshot<SnapshotTile>(
255	            snapshot.data(), src, static_cast<uint16_t>(blockMCount), sizeof(uint32_t), srcStride);
256	        set_flag(PIPE_MTE2, PIPE_S, ReadySnapshotEvent());
257	        wait_flag(PIPE_MTE2, PIPE_S, ReadySnapshotEvent());
258	    }
259	
260	    AICORE inline bool DiscoverReadyTickets(
261	        uint32_t stage, ReadyTracker& tracker, const ExpertTaskLayout& layout, uint32_t totalTasks) const
262	    {
263	        if (tracker.readyTail >= totalTasks) {
264	            return false;
265	        }
266	        AdvanceExpert(tracker.scanExpert, tracker.readyTail, stage, layout);
267	        const uint32_t expert = tracker.scanExpert;
268	        const uint32_t blockMCount =
269	            stage == static_cast<uint32_t>(MailboxStage::kGmm2) ? 1U : layout.gmm1TileM[expert];
270	        LoadReadyExpertSnapshot(stage, expert, blockMCount);
271	
272	        using SnapshotTile = PtoVecTile<uint32_t, kGmmProducerReadySnapshotMaxBlockM>;
273	        SnapshotTile snapshot(1, blockMCount);
274	        pto::TASSIGN(snapshot, kGmmProducerReadySnapshotUbBase);
275	        const uint32_t previousReadyTail = tracker.readyTail;
276	        const uint32_t expertTaskBase = layout.taskBase[stage][expert];
277	        const uint32_t expertTaskEnd = layout.taskBase[stage][expert + 1U];
278	        if (blockMCount == 1U) {
279	            if (snapshot.GetValue(0U) >= ReadyCounterExpected(stage, layout, expert, 0U)) {
280	                tracker.readyTail = expertTaskEnd;
281	            }
282	        } else {
283	            while (tracker.readyTail < expertTaskEnd) {
284	                const uint32_t expertLoop = tracker.readyTail - expertTaskBase;
285	                uint32_t blockM = 0U;
286	                uint32_t blockN = 0U;
287	                GmmCommonGetBlockCoordMN(expertLoop, blockMCount, layout.tileN[stage], blockM, blockN);
288	                (void)blockN;
289	                const uint32_t observed = snapshot.GetValue(blockM);
290	                if (observed < ReadyCounterExpected(stage, layout, expert, blockM)) {
291	                    break;
292	                }
293	                ++tracker.readyTail;
294	            }
295	        }
296	        if (tracker.readyTail >= expertTaskEnd) {
297	            ++tracker.scanExpert;
298	        }
299	        return tracker.readyTail != previousReadyTail;
300	    }
301	
302	    AICORE inline bool TakeReadyTicket(
303	        uint32_t stage, ReadyTracker& tracker, const ExpertTaskLayout& layout, uint32_t& localTicket) const
304	    {
305	        if (tracker.publishTail >= tracker.readyTail) {
306	            return false;
307	        }
308	        AdvanceExpert(tracker.publishExpert, tracker.publishTail, stage, layout);
309	        localTicket = tracker.publishTail++;
310	        AdvanceExpert(tracker.publishExpert, tracker.publishTail, stage, layout);
311	        return true;
312	    }
