321	    AICORE inline void FlushMailboxP2c(bool& p2cDirty)
322	    {
323	        if (!p2cDirty) {
324	            return;
325	        }
326	
327	        __gm__ uint32_t* p2cWords =
328	            reinterpret_cast<__gm__ uint32_t*>(workspaceGM_ + tilingData_->gmmSchedulerTiling.mailbox.p2cOffset);
329	        const event_t event = MailboxP2cEvent();
330	        pto::PtoSetWaitFlag<PIPE_S, PIPE_MTE3>(event, event);
331	        PtoStoreVector<uint32_t, kGmmProducerP2cShadowWords>(
332	            p2cWords, kGmmProducerP2cShadowUbBase, kGmmProducerP2cShadowWords);
333	        set_flag(PIPE_MTE3, PIPE_S, event);
334	        p2cWriteBusy_ = true;
335	        p2cDirty = false;
336	    }
337	
338	    AICORE inline void IssueProgressSnapshot(uint32_t slot, uint32_t aicCount) const
339	    {
340	        GmmProducerProgressSnapshotTile tile(1, aicCount * kGmmProducerProgressWordsPerLane);
341	        pto::TASSIGN(tile, ProgressSnapshotUbOffset(slot));
342	        __gm__ uint8_t* src =
343	            reinterpret_cast<__gm__ uint8_t*>(workspaceGM_ + tilingData_->gmmSchedulerTiling.mailbox.c2pOffset);
344	        const uint32_t bytes = aicCount * kGmmProducerProgressWordsPerLane * sizeof(uint32_t);
345	        LoadGmmSnapshot<GmmProducerProgressSnapshotTile>(tile.data(), src, 1U, bytes, bytes);
346	        set_flag(PIPE_MTE2, PIPE_S, ProgressSnapshotEvent(slot));
347	    }
348	
349	    AICORE inline void ProcessMailbox()
350	    {
351	        PtoFillUb<uint32_t, kGmmProducerP2cShadowWords>(kGmmProducerP2cShadowUbBase, 0U, kGmmProducerP2cShadowWords);
352	        GmmProducerP2cShadowTile p2cShadow(1, kGmmProducerP2cShadowWords);
353	        pto::TASSIGN(p2cShadow, kGmmProducerP2cShadowUbBase);
354	        pto::PtoSetWaitFlag<PIPE_V, PIPE_S>();
355	
356	        const uint32_t aicCount = tilingData_->fixedGroupTiling.physicalAicNum;
357	        const bool gmm1Mailbox =
358	            tilingData_->gmmSchedulerTiling.gmm1ScheduleMode == kMegaMoeGmm1ScheduleWave0MailboxSuffix;
359	
360	        MailboxLaneState lanes[kGmmProducerMaxAicCount] = {};
361	        ExpertTaskLayout taskLayout;
362	        InitExpertTaskLayout(taskLayout);
363	        constexpr uint32_t gmm1Stage = static_cast<uint32_t>(MailboxStage::kGmm1);
364	        constexpr uint32_t gmm2Stage = static_cast<uint32_t>(MailboxStage::kGmm2);
365	        const __gm__ MegaMoeFixedGroupTiling& fixed = tilingData_->fixedGroupTiling;
366	        const MegaMoeExpertWaveRange wave0 = GetExpertWaveRange(
367	            0U, expertPerRank_, fixed.fullAicExpertsPerWave, fixed.expertsPerWave, fixed.fullAicGmm1WaveCount);
368	        const uint32_t wave0ExpertEnd = wave0.end;
369	        uint32_t layoutExpert = 0U;
370	        while (layoutExpert < wave0ExpertEnd) {
371	            AppendExpertTaskLayout(taskLayout, layoutExpert);
372	            ++layoutExpert;
373	        }
374	        const uint32_t gmm1Wave0TaskCount = taskLayout.taskBase[gmm1Stage][wave0ExpertEnd];
375	        const uint32_t gmm2Wave0TaskCount = taskLayout.taskBase[gmm2Stage][wave0ExpertEnd];
376	        while (layoutExpert < expertPerRank_) {
377	            AppendExpertTaskLayout(taskLayout, layoutExpert);
378	            ++layoutExpert;
379	        }
380	        const uint32_t initialGmm1TaskCount = gmm1Mailbox ? gmm1Wave0TaskCount : 0U;
381	        const uint32_t initialGmm2TaskCount = gmm2Wave0TaskCount;
382	        ReadyTracker readyTrackers[kGmmProducerMailboxStageCount];
383	        // Ready discovery is independent of lane phases. Both shared suffix
384	        // pools start immediately after their stage-local direct wave0 prefix.
385	        readyTrackers[gmm1Stage].scanExpert = gmm1Mailbox ? wave0ExpertEnd : expertPerRank_;
386	        readyTrackers[gmm1Stage].publishExpert = gmm1Mailbox ? wave0ExpertEnd : expertPerRank_;
387	        readyTrackers[gmm1Stage].readyTail = initialGmm1TaskCount;
388	        readyTrackers[gmm1Stage].publishTail = initialGmm1TaskCount;
389	        readyTrackers[gmm2Stage].scanExpert = wave0ExpertEnd;
390	        readyTrackers[gmm2Stage].publishExpert = wave0ExpertEnd;
391	        readyTrackers[gmm2Stage].readyTail = initialGmm2TaskCount;
392	        readyTrackers[gmm2Stage].publishTail = initialGmm2TaskCount;
393	        uint64_t nextReadyTaskTick = 0U;
394	        uint32_t progressSnapshotSlot = 0U;
395	        IssueProgressSnapshot(progressSnapshotSlot, aicCount);
396	
397	        const uint32_t gmm1TaskCount = gmm1Mailbox ? taskLayout.taskBase[gmm1Stage][expertPerRank_] : 0U;
398	        const uint32_t gmm2TaskCount = taskLayout.taskBase[gmm2Stage][expertPerRank_];
399	        const uint32_t gmm1GroupSize = tilingData_->fixedGroupTiling.gmm1GroupSize;
400	        uint32_t doneLanes = 0U;
401	        uint32_t laneCursor = 0U;
402	        uint32_t readyStageCursor = gmm1Stage;
403	        bool gmm2Gate = false;
404	        uint64_t nextGateCheckTick = 0U;
405	        uint64_t nextMailboxTaskTick = 0U;
406	
407	        while (doneLanes < aicCount) {
408	            bool progressed = false;
409	
410	            // Task A: snapshot exactly one current expert every 1 us and
411	            // advance only the contiguous swizzled ready-ticket prefix.
412	            const uint64_t readyNow = get_sys_cnt();
413	            const bool gmm1ReadyIncomplete = gmm1Mailbox && readyTrackers[0].readyTail < gmm1TaskCount;
414	            const bool gmm2ReadyIncomplete = readyTrackers[1].readyTail < gmm2TaskCount;
415	            if ((gmm1ReadyIncomplete || gmm2ReadyIncomplete) && readyNow >= nextReadyTaskTick) {
416	                nextReadyTaskTick = readyNow + kGmmProducerReadyProbeIntervalTicks;
417	                uint32_t readyStage = readyStageCursor;
418	                if ((readyStage == static_cast<uint32_t>(MailboxStage::kGmm1) && !gmm1ReadyIncomplete) ||
419	                    (readyStage == static_cast<uint32_t>(MailboxStage::kGmm2) && !gmm2ReadyIncomplete)) {
420	                    readyStage ^= 1U;
421	                }
422	                const uint32_t readyTaskCount =
423	                    readyStage == static_cast<uint32_t>(MailboxStage::kGmm1) ? gmm1TaskCount : gmm2TaskCount;
424	                progressed = DiscoverReadyTickets(readyStage, readyTrackers[readyStage], taskLayout, readyTaskCount) ||
425	                             progressed;
426	                readyStageCursor = readyStage ^ 1U;
427	            }
428	
429	            // Task B: observe all 36 C2P progress words with one MTE load,
430	            // then refill empty single-ticket P2C slots. It never scans ready.
431	            const uint64_t mailboxNow = get_sys_cnt();
432	            if (mailboxNow >= nextMailboxTaskTick) {
433	                const uint32_t completedProgressSlot = progressSnapshotSlot;
434	                wait_flag(PIPE_MTE2, PIPE_S, ProgressSnapshotEvent(completedProgressSlot));
435	                const uint32_t nextProgressSlot = completedProgressSlot ^ 1U;
436	                IssueProgressSnapshot(nextProgressSlot, aicCount);
437	                progressSnapshotSlot = nextProgressSlot;
438	
439	                const uint64_t gateNow = get_sys_cnt();
440	                if (!gmm2Gate && gateNow >= nextGateCheckTick) {
441	                    if (Gmm2EntryGateReady()) {
442	                        gmm2Gate = true;
443	                    }
444	                    nextGateCheckTick = gateNow + kGmmProducerReadyProbeIntervalTicks;
445	                }
446	
447	                bool p2cDirty = false;
448	                GmmProducerProgressSnapshotTile completedProgress(1, aicCount * kGmmProducerProgressWordsPerLane);
449	                pto::TASSIGN(completedProgress, ProgressSnapshotUbOffset(completedProgressSlot));
450	                uint32_t physicalBlockId = laneCursor;
451	                for (uint32_t visit = 0U; visit < aicCount; ++visit) {
452	                    MailboxLaneState& lane = lanes[physicalBlockId];
453	                    const uint32_t progress =
454	                        completedProgress.GetValue(physicalBlockId * kGmmProducerProgressWordsPerLane);
455	                    const bool group2Lane = physicalBlockId >= gmm1GroupSize;
456	                    const GmmMailboxLanePhase observedPhase = ObserveGmmMailboxWave0End(
457	                        lane.phase, group2Lane, progress == kGmmMailboxGmm1Wave0EndTicket,
458	                        progress == kGmmMailboxGmm2Wave0EndTicket);
459	                    if (observedPhase != lane.phase) {
460	                        lane.phase = observedPhase;
461	                        progressed = true;
462	                    }
463	                    if (lane.phase != GmmMailboxLanePhase::kDone && lane.publishedTicket != kGmmMailboxEmptyTicket) {
464	                        if (progress == lane.publishedTicket) {
465	                            const uint32_t ticket = lane.publishedTicket;
466	                            lane.publishedTicket = kGmmMailboxEmptyTicket;
467	                            if (ticket == kGmmMailboxTerminalTicket) {
468	                                lane.phase = GmmMailboxLanePhase::kDone;
469	                                ++doneLanes;
470	                            }
471	                            progressed = true;
472	                        }
473	                    }
474	                    if (lane.phase != GmmMailboxLanePhase::kDone && lane.publishedTicket == kGmmMailboxEmptyTicket) {
475	                        for (uint32_t phaseAdvance = 0U; phaseAdvance < 2U; ++phaseAdvance) {
476	                            const GmmMailboxLanePhase advancedPhase = AdvanceGmmMailboxLanePhase(
477	                                lane.phase, readyTrackers[gmm1Stage].publishTail >= gmm1TaskCount, gmm2Gate,
478	                                readyTrackers[gmm2Stage].publishTail >= gmm2TaskCount);
479	                            if (advancedPhase == lane.phase) {
480	                                break;
481	                            }
482	                            lane.phase = advancedPhase;
483	                            progressed = true;
484	                        }
485	                        uint32_t localTicket = 0U;
486	                        bool published = false;
487	                        if (lane.phase == GmmMailboxLanePhase::kGmm1Pc) {
488	                            if (TakeReadyTicket(gmm1Stage, readyTrackers[gmm1Stage], taskLayout, localTicket)) {
489	                                StageMailboxWork(
490	                                    physicalBlockId, MailboxStage::kGmm1, localTicket, lane, p2cShadow, p2cDirty);
491	                                published = true;
492	                            }
493	                        } else if (lane.phase == GmmMailboxLanePhase::kGmm2Pc && gmm2Gate) {
494	                            if (TakeReadyTicket(gmm2Stage, readyTrackers[gmm2Stage], taskLayout, localTicket)) {
495	                                StageMailboxWork(
496	                                    physicalBlockId, MailboxStage::kGmm2, localTicket, lane, p2cShadow, p2cDirty);
497	                                published = true;
498	                            }
499	                        } else if (lane.phase == GmmMailboxLanePhase::kTerminalReady) {
500	                            StageMailboxTicket(physicalBlockId, kGmmMailboxTerminalTicket, lane, p2cShadow, p2cDirty);
501	                            published = true;
502	                        }
503	                        if (published) {
504	                            progressed = true;
505	                        }
506	                    }
507	                    AdvanceMailboxLane(physicalBlockId, aicCount);
508	                }
509	                if (doneLanes >= aicCount) {
510	                    wait_flag(PIPE_MTE2, PIPE_S, ProgressSnapshotEvent(progressSnapshotSlot));
511	                    break;
512	                }
513	                FlushMailboxP2c(p2cDirty);
514	                AdvanceMailboxLane(laneCursor, aicCount);
515	                nextMailboxTaskTick = mailboxNow + kGmmProducerMailboxTargetPeriodTicks;
516	            }
517	
518	            if (!progressed) {
519	                GmmPollBackoff();
520	            }
521	        }
522	        AcquireMailboxP2cWrite();
523	    }
524	
525	    AICORE inline uint32_t CurrentM(uint32_t expert) const
526	    {
527	        return MoeCurrentMRaw(cumsumMMPtr_, rankSize_, expertPerRank_, expert);
528	    }
529	
530	    GM_ADDR workspaceGM_ = nullptr;
531	    const __gm__ MegaMoeTilingData* tilingData_ = nullptr;
532	    __gm__ int32_t* cumsumMMPtr_ = nullptr;
533	    uint32_t rankSize_ = 0U;
534	    uint32_t expertPerRank_ = 0U;
535	    bool p2cWriteBusy_ = false;
536	};
537	
538	#endif // DISPATCH_MEGA_COMBINE_GMM_TASK_PRODUCER_H
539

