73	template <uint32_t SwizzleOffset>
74	AICORE inline void GmmCommonGetBlockCoordMNWithOffset(
75	    uint32_t loopIdx, uint32_t tileM, uint32_t tileN, uint32_t& blockM, uint32_t& blockN)
76	{
77	    static_assert(SwizzleOffset != 0U);
78	    const uint32_t tileBlockLoop = static_cast<uint32_t>(ceilDiv(tileN, SwizzleOffset));
79	    const uint32_t tileBlockIdx = loopIdx / (SwizzleOffset * tileM);
80	    const uint32_t inTileBlockIdx = loopIdx % (SwizzleOffset * tileM);
81	    uint32_t nCol = SwizzleOffset;
82	    if (tileBlockIdx + 1U == tileBlockLoop) {
83	        nCol = tileN - SwizzleOffset * tileBlockIdx;
84	    }
85	    blockM = inTileBlockIdx / nCol;
86	    blockN = tileBlockIdx * SwizzleOffset + inTileBlockIdx % nCol;
87	    if ((tileBlockIdx & 1U) != 0U) {
88	        blockM = tileM - blockM - 1U;
89	    }
90	}
